69	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
70	    }
71	
72	    @Override
73	    public void validate(Object target, Errors errors) {
74	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
75	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
76	        for (String field : REQUIRED_FIELDS) {
77	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
78	        }
